import 'package:flutter/material.dart';
import 'package:pagination_flutter/pagination_flutter.dart';

class MyHomePage extends StatefulWidget {const MyHomePage({Key? key}): super(key: key);}
class _MyHomePageState extends State<MyHomePage> {
  int selectedPage = 1;
  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Flutter Pagination')),
      body: Center(
        child: Pagination(
          numOfPages: 10,
          selectedPage: selectedPage,
          pagesVisible: 3,
          onPageChanged: (page) => setState(() => selectedPage = page),
          nextIcon: const Icon(Icons.arrow_forward_ios, color: Colors.blue, size: 14),
          previousIcon: const Icon(Icons.arrow_back_ios, color: Colors.blue, size: 14),
        ),
      ),
    );
  }
}
